MessageStreamEvent = Union[MessageStartEvent, ContentBlockStartEvent, ContentBlockDeltaEvent, ContentBlockStopEvent, MessageDeltaEvent, MessageStopEvent, PingEvent, ErrorEvent]
"""One server-sent event of a streamed Messages reply. Events of a type not listed here, such as ORBTR's orbtr.ai.* progress events, are passed through with their type and data."""

_MESSAGE_STREAM_EVENT_TYPES: dict[str, Any] = {
    "message_start": MessageStartEvent,
    "content_block_start": ContentBlockStartEvent,
    "content_block_delta": ContentBlockDeltaEvent,
    "content_block_stop": ContentBlockStopEvent,
    "message_delta": MessageDeltaEvent,
    "message_stop": MessageStopEvent,
    "ping": PingEvent,
    "error": ErrorEvent,
}


def parse_message_stream_event(data: dict[str, Any]) -> MessageStreamEvent:
    """Reads one MessageStreamEvent by its type."""
    cls = _MESSAGE_STREAM_EVENT_TYPES.get(data.get("type"))
    if cls is None:
        raise ValueError(f"not a MessageStreamEvent: {data.get('type')!r}")
    return cls.from_dict(data)


